<?php
declare(strict_types=1);
date_default_timezone_set('Asia/Manila');
$sessionDir = __DIR__ . '/.sessions';
if (!is_dir($sessionDir)) mkdir($sessionDir, 0700, true);
session_save_path($sessionDir);
session_start();
$db = new PDO('sqlite:' . __DIR__ . '/scholarships.sqlite');
$db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
$db->exec('PRAGMA foreign_keys = ON');

function out($data, int $code=200): never { http_response_code($code); header('Content-Type: application/json'); echo json_encode($data); exit; }
function user(): ?array { return $_SESSION['user'] ?? null; }
function mustLogin(): array { $u=user(); if(!$u) out(['error'=>'Please sign in.'],401); return $u; }
function mustStaff(): array { $u=mustLogin(); if($u['role']!=='staff') out(['error'=>'Staff access required.'],403); return $u; }
function logChange(PDO $db, int $submission, array $u, string $type, string $details=''): void { $s=$db->prepare('INSERT INTO history(submission_id,actor_id,actor_name,event_type,details,created_at) VALUES(?,?,?,?,?,?)'); $s->execute([$submission,$u['id'],$u['name'],$type,$details,date('c')]); }
function deadline(string $created): bool { return strtotime($created) <= strtotime('2026-10-30 17:00:00 +0800'); }

$db->exec("CREATE TABLE IF NOT EXISTS profiles (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id TEXT UNIQUE, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('scholar','staff')));
CREATE TABLE IF NOT EXISTS programs (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, max_gwa REAL NOT NULL, min_units INTEGER NOT NULL, max_failed INTEGER NOT NULL, max_incomplete INTEGER NOT NULL, max_dropped INTEGER NOT NULL, deadline TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, scholar_id INTEGER UNIQUE NOT NULL, program_id INTEGER NOT NULL, FOREIGN KEY(scholar_id) REFERENCES profiles(id), FOREIGN KEY(program_id) REFERENCES programs(id));
CREATE TABLE IF NOT EXISTS submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, scholar_id INTEGER NOT NULL, academic_year TEXT NOT NULL, semester TEXT NOT NULL, gwa REAL NOT NULL, units INTEGER NOT NULL, failed INTEGER NOT NULL, incomplete INTEGER NOT NULL, dropped INTEGER NOT NULL, evidence_ref TEXT NOT NULL, submitted_at TEXT NOT NULL, verification_status TEXT NOT NULL DEFAULT 'Pending', verification_reason TEXT, compliance_result TEXT NOT NULL DEFAULT 'Not evaluated', compliance_reasons TEXT, renewal_decision TEXT NOT NULL DEFAULT 'Not decided', decision_notes TEXT, UNIQUE(scholar_id,academic_year,semester), FOREIGN KEY(scholar_id) REFERENCES profiles(id));
CREATE TABLE IF NOT EXISTS history (id INTEGER PRIMARY KEY AUTOINCREMENT, submission_id INTEGER NOT NULL, actor_id INTEGER, actor_name TEXT NOT NULL, event_type TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL, FOREIGN KEY(submission_id) REFERENCES submissions(id));");

if(!(int)$db->query('SELECT COUNT(*) FROM profiles')->fetchColumn()) {
  $db->beginTransaction();
  $ins=$db->prepare('INSERT INTO profiles(student_id,name,email,password,role) VALUES(?,?,?,?,?)');
  $ins->execute([null,'Maria Santos, Scholarship Staff','staff@demo.edu',password_hash('Staff123!',PASSWORD_DEFAULT),'staff']);
  $staff=(int)$db->lastInsertId();
  $program=$db->prepare('INSERT INTO programs(name,max_gwa,min_units,max_failed,max_incomplete,max_dropped,deadline) VALUES(?,?,?,?,?,?,?)');
  $program->execute(['Merit Scholar',1.75,18,0,0,0,'2026-10-30 17:00:00 +0800']); $merit=(int)$db->lastInsertId();
  $program->execute(['Community Scholar',2.25,15,0,0,1,'2026-10-30 17:00:00 +0800']); $community=(int)$db->lastInsertId();
  $names=['A01'=>'Ariana Cruz','A02'=>'Ben Flores','A03'=>'Carla Reyes','A04'=>'Dino Lim','A05'=>'Elena Ramos','A06'=>'Francis Yu'];
  $rows=[['A01',$merit,1.75,18,0,0,0,'2026-10-30 17:00:00 +0800','Verified'],['A02',$merit,1.76,18,0,0,0,'2026-10-29 17:00:00 +0800','Verified'],['A03',$community,2.25,15,0,0,1,'2026-10-29 17:00:00 +0800','Verified'],['A04',$community,2.25,14,0,1,0,'2026-10-29 17:00:00 +0800','Verified'],['A05',$merit,1.50,18,1,0,0,'2026-10-30 17:01:00 +0800','Verified'],['A06',$community,2.00,15,0,0,0,'2026-10-29 17:00:00 +0800','Pending']];
  $add=$db->prepare('INSERT INTO profiles(student_id,name,email,password,role) VALUES(?,?,?,?,?)'); $assign=$db->prepare('INSERT INTO assignments(scholar_id,program_id) VALUES(?,?)'); $sub=$db->prepare('INSERT INTO submissions(scholar_id,academic_year,semester,gwa,units,failed,incomplete,dropped,evidence_ref,submitted_at,verification_status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');
  foreach($rows as $r){ $id=$r[0]; $add->execute([$id,$names[$id],strtolower($id).'@demo.edu',password_hash('Scholar123!',PASSWORD_DEFAULT),'scholar']); $sid=(int)$db->lastInsertId(); $assign->execute([$sid,$r[1]]); $sub->execute([$sid,'2026-2027','1',$r[2],$r[3],$r[4],$r[5],$r[6],"GRADE-$id-2026.pdf",$r[7],$r[8]]); }
  $db->commit();
}

$action=$_GET['action'] ?? '';
if ($action === '') {
  header('Content-Type: text/html; charset=utf-8');
  ?>
  <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ScholarTrack</title><link rel="stylesheet" href="style.css?v=<?= filemtime(__DIR__ . '/style.css') ?>"></head><body><main class="login card"><p>Loading ScholarTrack…</p></main><script>window.addEventListener('error',function(e){if((e.filename||'').includes('app.js'))document.body.innerHTML='<main class="login card"><h1>Startup error</h1><p class="notice error">'+(e.message||'Unable to run app.js')+'</p><p>Copy this message and send it to the developer.</p></main>'});window.addEventListener('unhandledrejection',function(e){document.body.innerHTML='<main class="login card"><h1>Startup error</h1><p class="notice error">'+(e.reason&&e.reason.message||'Unexpected application error')+'</p></main>'});</script><script src="app.js?v=<?= filemtime(__DIR__ . '/app.js') ?>" onerror="document.body.innerHTML='<main class=\"login card\"><h1>Unable to load ScholarTrack</h1><p>Start the site through PHP, then reload this page.</p></main>'"></script></body></html>
  <?php exit;
}
if($action==='login') { $v=json_decode(file_get_contents('php://input'),true)??[]; $s=$db->prepare('SELECT * FROM profiles WHERE email=?'); $s->execute([strtolower(trim($v['email']??''))]); $p=$s->fetch(PDO::FETCH_ASSOC); if(!$p || !password_verify($v['password']??'',$p['password'])) out(['error'=>'Invalid email or password.'],401); $_SESSION['user']=['id'=>(int)$p['id'],'name'=>$p['name'],'role'=>$p['role'],'student_id'=>$p['student_id']]; out(['user'=>user()]); }
if($action==='logout') { session_destroy(); out(['ok'=>true]); }
if($action==='me') out(['user'=>user()]);
if($action==='programs') { mustLogin(); out(['programs'=>$db->query('SELECT * FROM programs ORDER BY id')->fetchAll(PDO::FETCH_ASSOC)]); }
if($action==='list') { $u=mustLogin(); $where=$u['role']==='staff'?'':' WHERE s.scholar_id='.(int)$u['id']; $q="SELECT s.*,p.student_id,p.name,a.program_id,pr.name program,pr.max_gwa,pr.min_units,pr.max_failed,pr.max_incomplete,pr.max_dropped,pr.deadline FROM submissions s JOIN profiles p ON p.id=s.scholar_id JOIN assignments a ON a.scholar_id=p.id JOIN programs pr ON pr.id=a.program_id".$where.' ORDER BY s.submitted_at DESC'; $total=$u['role']==='staff' ? (int)$db->query('SELECT COUNT(*) FROM assignments')->fetchColumn() : 1; out(['submissions'=>$db->query($q)->fetchAll(PDO::FETCH_ASSOC),'assigned_total'=>$total]); }
if($action==='history') { $u=mustLogin(); $id=(int)($_GET['id']??0); $q=$db->prepare('SELECT s.scholar_id FROM submissions s WHERE s.id=?');$q->execute([$id]);$owner=$q->fetchColumn();if(!$owner || ($u['role']!=='staff'&&(int)$owner!==$u['id']))out(['error'=>'Not authorized.'],403); $h=$db->prepare('SELECT * FROM history WHERE submission_id=? ORDER BY created_at DESC');$h->execute([$id]);out(['history'=>$h->fetchAll(PDO::FETCH_ASSOC)]); }
if($action==='submit') { $u=mustLogin(); if($u['role']!=='scholar')out(['error'=>'Only scholars can submit.'],403); $v=json_decode(file_get_contents('php://input'),true)??[]; foreach(['academic_year','semester','evidence_ref'] as $f)if(trim((string)($v[$f]??''))==='')out(['error'=>"$f is required."],422); $gwa=(float)($v['gwa']??0); $nums=['units','failed','incomplete','dropped']; if($gwa<1||$gwa>5)out(['error'=>'GWA must be from 1.00 to 5.00.'],422);foreach($nums as $n)if(!isset($v[$n])||filter_var($v[$n],FILTER_VALIDATE_INT)===false||(int)$v[$n]<0)out(['error'=>"$n must be a nonnegative integer."],422); try{$s=$db->prepare("INSERT INTO submissions(scholar_id,academic_year,semester,gwa,units,failed,incomplete,dropped,evidence_ref,submitted_at) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$u['id'],$v['academic_year'],$v['semester'],$gwa,$v['units'],$v['failed'],$v['incomplete'],$v['dropped'],trim($v['evidence_ref']),date('c')]);$id=(int)$db->lastInsertId();logChange($db,$id,$u,'Submitted','Academic summary submitted');out(['ok'=>true]);}catch(PDOException $e){out(['error'=>'A submission for this academic year and semester already exists.'],409);} }
if($action==='resubmit') { $u=mustLogin();$v=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($v['id']??0);$q=$db->prepare('SELECT * FROM submissions WHERE id=? AND scholar_id=?');$q->execute([$id,$u['id']]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r||$u['role']!=='scholar')out(['error'=>'Not authorized.'],403);if($r['verification_status']!=='Returned')out(['error'=>'Only returned submissions can be corrected.'],422);if(trim((string)($v['evidence_ref']??''))==='')out(['error'=>'A grade-document reference is required.'],422);$s=$db->prepare("UPDATE submissions SET evidence_ref=?,verification_status='Pending',verification_reason=NULL,compliance_result='Not evaluated',compliance_reasons=NULL,renewal_decision='Not decided',decision_notes=NULL,submitted_at=? WHERE id=?");$s->execute([trim($v['evidence_ref']),date('c'),$id]);logChange($db,$id,$u,'Resubmitted','Correction submitted; returned to Pending verification');out(['ok'=>true]); }
if($action==='verify') { $u=mustStaff();$v=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($v['id']??0);$status=$v['status']??'';if(!in_array($status,['Verified','Returned'],true))out(['error'=>'Invalid verification status.'],422);if($status==='Returned'&&trim($v['reason']??'')==='')out(['error'=>'A return reason is required.'],422);$s=$db->prepare('UPDATE submissions SET verification_status=?,verification_reason=?,compliance_result="Not evaluated",compliance_reasons=NULL WHERE id=?');$s->execute([$status,trim($v['reason']??''),$id]);logChange($db,$id,$u,"Evidence $status",trim($v['reason']??''));out(['ok'=>true]); }
if($action==='evaluate') { $u=mustStaff();$v=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($v['id']??0);$q=$db->prepare('SELECT s.*,pr.* FROM submissions s JOIN assignments a ON a.scholar_id=s.scholar_id JOIN programs pr ON pr.id=a.program_id WHERE s.id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)out(['error'=>'Submission not found.'],404);if($r['verification_status']!=='Verified')out(['error'=>'Only verified evidence may be evaluated.'],422);$reasons=[];if($r['gwa']>$r['max_gwa'])$reasons[]="GWA {$r['gwa']} exceeds maximum {$r['max_gwa']}";if($r['units']<$r['min_units'])$reasons[]="Enrolled units {$r['units']} below minimum {$r['min_units']}";if($r['failed']>$r['max_failed'])$reasons[]="Failed subjects {$r['failed']} exceed allowed {$r['max_failed']}";if($r['incomplete']>$r['max_incomplete'])$reasons[]="Incomplete grades {$r['incomplete']} exceed allowed {$r['max_incomplete']}";if($r['dropped']>$r['max_dropped'])$reasons[]="Dropped subjects {$r['dropped']} exceed allowed {$r['max_dropped']}";if(!deadline($r['submitted_at']))$reasons[]='Submitted after the 2026-10-30 17:00 Manila deadline';$result=$reasons?'With Deficiency':'Compliant';$s=$db->prepare('UPDATE submissions SET compliance_result=?,compliance_reasons=? WHERE id=?');$s->execute([$result,json_encode($reasons),$id]);logChange($db,$id,$u,'Evaluated',"$result: ".implode('; ',$reasons));out(['ok'=>true,'result'=>$result,'reasons'=>$reasons]); }
if($action==='decide') { $u=mustStaff();$v=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($v['id']??0);$decision=$v['decision']??'';$q=$db->prepare('SELECT compliance_result,verification_status FROM submissions WHERE id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)out(['error'=>'Submission not found.'],404);if(!in_array($decision,['Approved','Held'],true))out(['error'=>'Invalid decision.'],422);if($decision==='Approved'&&($r['verification_status']!=='Verified'||$r['compliance_result']!=='Compliant'))out(['error'=>'Only verified, compliant submissions may be approved.'],422);$s=$db->prepare('UPDATE submissions SET renewal_decision=?,decision_notes=? WHERE id=?');$s->execute([$decision,trim($v['notes']??''),$id]);logChange($db,$id,$u,"Renewal $decision",trim($v['notes']??''));out(['ok'=>true]); }
if($action==='register') { $u=mustStaff();$v=json_decode(file_get_contents('php://input'),true)??[];foreach(['student_id','name','email','program_id'] as $f)if(trim((string)($v[$f]??''))==='')out(['error'=>"$f is required."],422);try{$db->beginTransaction();$s=$db->prepare('INSERT INTO profiles(student_id,name,email,password,role) VALUES(?,?,?,?,"scholar")');$s->execute([trim($v['student_id']),trim($v['name']),strtolower(trim($v['email'])),password_hash($v['password']??'Scholar123!',PASSWORD_DEFAULT)]);$id=(int)$db->lastInsertId();$a=$db->prepare('INSERT INTO assignments(scholar_id,program_id) VALUES(?,?)');$a->execute([$id,$v['program_id']]);$db->commit();out(['ok'=>true]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();out(['error'=>'Student ID or email already exists.'],409);} }
out(['error'=>'Unknown request.'],404);
?>
